mapper.select:
SELECT COUNT(*) FROM (
    SELECT o.id FROM orders o

        AND o.status = #{status}
        AND o.delivery_way = #{deliveryWay}
        AND o.id LIKE CONCAT('%', #{orderNumber}, '%')
        AND o.phone LIKE CONCAT('%', #{phone}, '%')

    UNION ALL
    SELECT s.id FROM second_hand_order s

        1 = 1
        AND s.status = #{status}
        AND s.delivery_way = #{deliveryWay}
        AND s.id LIKE CONCAT('%', #{orderNumber}, '%')
        AND s.phone LIKE CONCAT('%', #{phone}, '%')

) c

SELECT * FROM (
    SELECT o.id, o.user_id AS userId, o.total_amount AS totalAmount, o.status, o.pay_status AS payStatus,
           o.phone, o.consignee, o.delivery_way AS deliveryWay, o.order_time AS orderTime
    FROM orders o

        AND o.status = #{status}
        AND o.delivery_way = #{deliveryWay}
        AND o.id LIKE CONCAT('%', #{orderNumber}, '%')
        AND o.phone LIKE CONCAT('%', #{phone}, '%')

    UNION ALL
    SELECT s.id, s.user_id AS userId, s.total_amount AS totalAmount, s.status, s.pay_status AS payStatus,
           s.phone, s.consignee, s.delivery_way AS deliveryWay, s.order_time AS orderTime
    FROM second_hand_order s

        1 = 1
        AND s.status = #{status}
        AND s.delivery_way = #{deliveryWay}
        AND s.id LIKE CONCAT('%', #{orderNumber}, '%')
        AND s.phone LIKE CONCAT('%', #{phone}, '%')

) t
ORDER BY t.orderTime DESC
LIMIT #{offset}, #{limit}
